Toast.Variants:
export const Variants = () => (
  <ToastProvider>
    <div className="p-4">
      <VariantsTrigger />
    </div>
    <Toaster />
  </ToastProvider>
)

function ActionTrigger() {
  const toast = useToast()
  return (
    <Button
      onClick={() =>
        toast.add({
          type: 'info',
          title: 'Item deleted',
          description: 'The record has been removed.',
          action: { label: 'Undo', onClick: () => console.log('undo') },
        })
      }
    >
      Delete item
    </Button>
  )
}

